"use no memo";
import React from 'react';
import {
  FlexWidget,
  ImageWidget,
  TextWidget,
} from 'react-native-android-widget';
import type { ColorProp } from 'react-native-android-widget';

import type { WidgetData } from './data';

const CARD: ColorProp    = '#202020';
const NAVBAR: ColorProp  = '#121212';
const TEXT: ColorProp    = '#FFFFFF';
const MUTED: ColorProp   = '#9E9E9E';
const PRIMARY: ColorProp = '#FFC107';
const ACCENT_BG          = '#1A2A00' as ColorProp;

const IMG_HOME  = 'data:image/png;base64,';
const IMG_NAV   = 'data:image/png;base64,';
const IMG_PLAY  = 'data:image/png;base64,';
const IMG_PAUSE = 'data:image/png;base64,';
const IMG_STOP  = 'data:image/png;base64,';
const IMG_GAS   = 'data:image/png;base64,';
const IMG_RESET = 'data:image/png;base64,';

export interface AllInOneWidgetProps extends WidgetData {
  shortcuts: { name: string; lat: number | null; lng: number | null }[];
  tripStatus?: 'idle' | 'active' | 'paused';
  spinAngle?: number;
}

function ImgBtn({
  image,
  clickAction,
  bg = CARD,
}: {
  image: string;
  clickAction: string;
  bg?: ColorProp;
}) {
  return (
    <FlexWidget
      clickAction={clickAction}
      style={{
        flex: 1,
        height: 'match_parent',
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: bg,
        borderRadius: 8,
      }}
    >
      <ImageWidget
        image={image as any}
        imageWidth={22}
        imageHeight={22}
        style={{ width: 22, height: 22 }}
      />
    </FlexWidget>
  );
}

export function AllInOneWidget({
  tasks,
  widgetAppts,
  todayWork,
  todayDayNum,
  marieCircleColor,
  tripStatus = 'idle',
}: AllInOneWidgetProps) {
  const isRepos  = todayWork === 'Repos';
  const nextAppt = widgetAppts[0] ?? null;

  return (
    <FlexWidget
      clickAction="OPEN_APP"
      style={{
        height: 'match_parent',
        width: 'match_parent',
        backgroundColor: NAVBAR,
        borderRadius: 14,
        paddingHorizontal: 8,
        paddingTop: 5,
        paddingBottom: 5,
        flexDirection: 'column',
        flexGap: 4,
      }}
    >
      {/* ─── Ligne 1 : infos ─── */}
      <FlexWidget
        style={{
          width: 'match_parent',
          flexDirection: 'row',
          alignItems: 'center',
          flex: 1,
          flexGap: 6,
        }}
      >
        <FlexWidget
          clickAction="OPEN_URI"
          clickActionData={{ uri: 'yoann2:///marie' }}
          style={{
            width: 24,
            height: 24,
            borderRadius: 12,
            backgroundColor: marieCircleColor as ColorProp,
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          <TextWidget
            text={String(todayDayNum)}
            style={{ fontSize: 11, fontWeight: 'bold', color: '#FFFFFF' }}
          />
        </FlexWidget>

        <FlexWidget style={{ flex: 1, flexDirection: 'row', alignItems: 'center' }}>
          <TextWidget
            text={isRepos ? 'Repos' : todayWork}
            style={{ fontSize: 11, color: isRepos ? MUTED : PRIMARY, fontWeight: 'bold' }}
            maxLines={1}
            truncate="END"
          />
        </FlexWidget>

        <TextWidget
          text={`${tasks.length} tache${tasks.length > 1 ? 's' : ''}`}
          style={{ fontSize: 10, color: TEXT }}
        />

        {nextAppt ? (
          <TextWidget
            text={`· ${nextAppt.title}`}
            style={{ fontSize: 10, color: PRIMARY }}
            maxLines={1}
            truncate="END"
          />
        ) : null}
      </FlexWidget>

      {/* ─── Ligne 2 : boutons ─── */}
      <FlexWidget
        style={{
          flexDirection: 'row',
          width: 'match_parent',
          height: 28,
          alignItems: 'center',
          flexGap: 5,
        }}
      >
        <ImgBtn image={IMG_NAV}  clickAction="NAVIGATE_TO" />
        <ImgBtn image={IMG_HOME} clickAction="NAVIGATE_HOME" />

        {tripStatus === 'idle' && (
          <ImgBtn image={IMG_PLAY} clickAction="MANUAL_TRIP_START" bg={ACCENT_BG} />
        )}
        {tripStatus === 'active' && (
          <ImgBtn image={IMG_PAUSE} clickAction="MANUAL_TRIP_PAUSE" />
        )}
        {tripStatus === 'active' && (
          <ImgBtn image={IMG_STOP} clickAction="MANUAL_TRIP_END" />
        )}
        {tripStatus === 'paused' && (
          <ImgBtn image={IMG_PLAY} clickAction="MANUAL_TRIP_RESUME" bg={ACCENT_BG} />
        )}
        {tripStatus === 'paused' && (
          <ImgBtn image={IMG_STOP} clickAction="MANUAL_TRIP_END" />
        )}

        <ImgBtn image={IMG_GAS}   clickAction="OPEN_FUEL" />
        <ImgBtn image={IMG_RESET} clickAction="REFRESH" />
      </FlexWidget>
    </FlexWidget>
  );
}
